composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      PGRST_DB_URI: "postgres://postgrest:{{env.POSTGRES_PASSWORD}}@{{serviceName}}-postgres:5432/postgrest"
      PGRST_DB_ANON_ROLE: {{env.PGRST_DB_ANON_ROLE}}
      PGRST_JWT_SECRET: {{env.PGRST_JWT_SECRET}}
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: postgres:16-alpine
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: postgrest
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      POSTGRES_DB: postgrest
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
